WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_grass_b_standard'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '标准牛吃草模型', 'kp-grass-b-standard', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "标准牛吃草模型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "两个方程求解 X 和 Y，再代入第三种情况求未知数。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[根据给出的两种吃草情况, 列出两个方程] --> B[Y = (N1 - X) * T1]\nB --> C[Y = (N2 - X) * T2]\nC --> D[联立解出草的生长速度 X]\nD --> E[代回任意方程得出原有草量 Y]\nE --> F[拿着已知身世的 Y 和 X, 去解题目最后一问的方程]"}}]}$$ AS jsonb), NULL, '标准牛吃草模型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "牛吃草问题", "标准牛吃草模型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_grass_b_standard", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
